package store

import (
	"context"
	"testing"
)

type gsrWitnessReader struct {
	calls int
}

// Read mimics the behavior of a real Reader in this project, which surfaces context cancellation.
func (r *gsrWitnessReader) Read(ctx context.Context, key string) (string, error) {
	r.calls++
	if err := ctx.Err(); err != nil {
		return "", err
	}
	return "", ErrRetry
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	r := &gsrWitnessReader{}
	_, err := Fetch(ctx, r, "testkey")

	if r.calls == 3 {
		t.Fatalf("Fetch() called Read 3 times with a cancelled context, want < 3")
	}
	if err == ErrGiveUp {
		t.Fatalf("Fetch() returned ErrGiveUp with a cancelled context, want context error")
	}
}

