package recruiter

import (
	"context"
	"errors"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrWitnessStorage struct {
	storage.Client
}

func (m *gsrWitnessStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	return []byte(`{}`), "etag1", nil
}

func (m *gsrWitnessStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel() // Cancel immediately to verify if the retry loop aborts

	s := &Store{
		Storage: &gsrWitnessStorage{},
		Bucket:  "test-bucket",
	}

	_, err := s.Mutate(ctx, "http://profile", func(c Contact) Contact { return c })
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("Store.Mutate with canceled context = %v, want error wrapping context.Canceled", err)
	}
}

package recruiter

import (
	"context"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrWitnessFakeStorage struct {
	storage.Client
	writeCalls int
	cancelFunc context.CancelFunc
}

func (f *gsrWitnessFakeStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	// Do not check ctx.Err() here to ensure we only test Store.Mutate's own loop handling.
	return []byte(`{}`), "etag1", nil
}

func (f *gsrWitnessFakeStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	f.writeCalls++
	if f.writeCalls == 1 && f.cancelFunc != nil {
		// Cancel the context as soon as the first write hits a conflict.
		f.cancelFunc()
	}
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	fake := &gsrWitnessFakeStorage{cancelFunc: cancel}
	s := &Store{
		Storage: fake,
		Bucket:  "test-bucket",
	}

	_, _ = s.Mutate(ctx, "https://linkedin.com/in/test", func(c Contact) Contact {
		return c
	})

	if fake.writeCalls >= maxWriteRetries {
		t.Fatalf("Store.Mutate(ctx, ...) exhausted all %d write retries despite context cancellation, want early abort", maxWriteRetries)
	}
}

